ALTER TABLE "alerta" DROP CONSTRAINT "alerta_tipo_check";--> statement-breakpoint
ALTER TABLE "alerta" DROP CONSTRAINT "alerta_alvo";--> statement-breakpoint
ALTER TABLE "equipe" ADD COLUMN "representante_id" uuid;--> statement-breakpoint
ALTER TABLE "equipe" ADD COLUMN "representacao_desde" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "equipe" ADD COLUMN "representacao_motivo" text;--> statement-breakpoint
ALTER TABLE "usuario" ADD COLUMN "ultima_atividade_em" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint
ALTER TABLE "alerta" ADD COLUMN "equipe_id" uuid;--> statement-breakpoint
ALTER TABLE "equipe" ADD CONSTRAINT "equipe_representante_id_usuario_id_fk" FOREIGN KEY ("representante_id") REFERENCES "public"."usuario"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "alerta" ADD CONSTRAINT "alerta_equipe_id_equipe_id_fk" FOREIGN KEY ("equipe_id") REFERENCES "public"."equipe"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "equipe_representante_idx" ON "equipe" USING btree ("representante_id");--> statement-breakpoint
ALTER TABLE "equipe" ADD CONSTRAINT "equipe_representacao_completa" CHECK (("equipe"."representacao_desde" is null) = ("equipe"."representacao_motivo" is null));--> statement-breakpoint
ALTER TABLE "equipe" ADD CONSTRAINT "equipe_representacao_motivo_check" CHECK ("equipe"."representacao_motivo" in ('ausencia', 'inatividade'));--> statement-breakpoint
ALTER TABLE "equipe" ADD CONSTRAINT "equipe_representante_diferente" CHECK ("equipe"."representante_id" is null or "equipe"."supervisor_id" is null or "equipe"."representante_id" <> "equipe"."supervisor_id");--> statement-breakpoint
ALTER TABLE "alerta" ADD CONSTRAINT "alerta_tipo_check" CHECK ("alerta"."tipo" in ('bloqueio', 'conflito_planejamento', 'execucao_duplicada', 'apoio_encerrado', 'falha_importacao', 'preventiva_proxima', 'preventiva_vencida', 'inspecao_com_pendencia', 'ausencia_pedida', 'ausencia_aprovada', 'ausencia_recusada', 'ausencia_registrada', 'ausencia_fim_pedido', 'ausencia_fim_respondido', 'ausencia_alterada', 'ausencia_vencida', 'ausencia_cancelada', 'representacao_iniciada', 'representacao_encerrada'));--> statement-breakpoint
ALTER TABLE "alerta" ADD CONSTRAINT "alerta_alvo" CHECK (("alerta"."tipo" = 'falha_importacao' and "alerta"."importacao_id" is not null and "alerta"."os_id" is null and "alerta"."ausencia_id" is null and "alerta"."equipe_id" is null) or ("alerta"."tipo" in ('ausencia_pedida', 'ausencia_aprovada', 'ausencia_recusada', 'ausencia_registrada', 'ausencia_fim_pedido', 'ausencia_fim_respondido', 'ausencia_alterada', 'ausencia_vencida', 'ausencia_cancelada') and "alerta"."ausencia_id" is not null and "alerta"."os_id" is null and "alerta"."importacao_id" is null and "alerta"."equipe_id" is null) or ("alerta"."tipo" in ('representacao_iniciada', 'representacao_encerrada') and "alerta"."equipe_id" is not null and "alerta"."os_id" is null and "alerta"."importacao_id" is null and "alerta"."ausencia_id" is null) or ("alerta"."tipo" <> 'falha_importacao' and not "alerta"."tipo" in ('ausencia_pedida', 'ausencia_aprovada', 'ausencia_recusada', 'ausencia_registrada', 'ausencia_fim_pedido', 'ausencia_fim_respondido', 'ausencia_alterada', 'ausencia_vencida', 'ausencia_cancelada') and not "alerta"."tipo" in ('representacao_iniciada', 'representacao_encerrada') and "alerta"."os_id" is not null and "alerta"."importacao_id" is null and "alerta"."ausencia_id" is null and "alerta"."equipe_id" is null));--> statement-breakpoint
-- Toda equipe com gente já nasce com representante: o membro mais antigo (criado_em nulo primeiro, depois pelo nome) que não é o supervisor.
UPDATE "equipe" SET "representante_id" = (SELECT u."id" FROM "usuario" u WHERE u."equipe_id" = "equipe"."id" AND u."ativo" AND u."liberacao" = 'liberado' AND u."perfil" = 'tecnico' AND u."id" IS DISTINCT FROM "equipe"."supervisor_id" ORDER BY u."criado_em" NULLS FIRST, u."nome", u."id" LIMIT 1);
